INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by)
VALUES ('TensorLBM', 'm15464 CASE-RAYLEIGH-BENARD-RA1E4', 15814, 2, $json${"impl_files": ["benchmarks/case_rayleigh_benard_ra1e4/run.py", "benchmarks/case_rayleigh_benard_ra1e4/ladder.py", "benchmarks/case_rayleigh_benard_ra1e4/make_figures.py", "src/tensorlbm/thermal.py"], "entry": "benchmarks/case_rayleigh_benard_ra1e4/run.py", "run_artifacts": ["/root/tp-agent/work/m15464/runs/case_rayleigh_benard_ra1e4/local_nx24_tau0.9.json", "/root/tp-agent/work/m15464/runs/case_rayleigh_benard_ra1e4/local_nx32_tau0.9.json", "/root/tp-agent/work/m15464/runs/case_rayleigh_benard_ra1e4/local_nx48_tau0.9.json"], "tests": ["AUDIT RERUN: pytest tests/test_thermal.py tests/test_heat_convection_benchmarks.py tests/test_conjugate_thermal_ddf.py -q -> 53 passed in 93.63s (matches self-report 53 passed/92s)", "NO case-level guard: tests/ has no test_case_rayleigh_benard*; tests/test_thermal.py:169-179 only asserts nu_grad2>0 / u_max>1e-4 (always true)"], "integration_callers": ["benchmarks/case_rayleigh_benard_ra1e4/run.py (the delivered harness itself) -> simulate_natural_convection; no production/platform caller, no tensor_benchmark_cases wiring", "tests/test_thermal.py:169 -> simulate_natural_convection (pre-existing sanity test)"], "benchmark": {"ref": {"source": "de Vahl Davis 1983 IJNMF 3:249-264", "Nu": 2.243, "u_max/(alpha/L)": 16.178, "v_max/(alpha/L)": 19.617}, "got": {"Nu": {"nx24": 1.7193, "nx32": 1.8897, "nx48": 2.0389}, "u_max_pos": {"nx32": 16.438, "nx48": 16.102}, "abs_u_min_mirror": {"nx32": 17.629, "nx48": 16.662}, "v_max": {"nx32": 19.791, "nx48": 19.32}}, "err_pct": {"Nu_nx48": -9.1, "Nu_nx32": -15.75, "Nu_nx24": -23.35, "u_max_pos_nx32": 1.6, "u_max_pos_nx48": -0.47, "abs_u_min_nx32": 8.97, "abs_u_min_nx48": 2.99, "v_max_nx32": 0.89, "v_max_nx48": -1.51}, "door": "predeclared |Nu/Nu_ref-1| < 5% -> Nu FAILS at all three delivered grids (best -9.10%)", "ledger": "tensor_benchmark_cases: SELECT case_name,metric,tolerance WHERE anchor_slug='CASE-RAYLEIGH-BENARD-RA1E4' -> 0 rows (table has 22 anchors, none matches) => no platform referee row exists", "richardson_two_point": "32->48: p=1 -> 2.337 (+4.21%), p=2 -> 2.158 (-3.77%); brackets ref but order p is undetermined, so this is a bracket not a convergence proof"}, "repro_cmd": "cd <TensorLBM checkout> && python benchmarks/case_rayleigh_benard_ra1e4/run.py --nx 24 --tau 0.9 --steps 40000 --report-every 2000 --out /tmp/audit_nx24.json  # AUDIT RERUN reproduced the committed nx=24 artifact field-by-field: Nu=1.719326, 20-sample Nu history max|dNu|=0.0, elapsed 128.6s. repro.sh itself covers only nx=24+32; the headline nx=48 (798.5s) needs a manual command", "external_anchor": "de Vahl Davis M. (1983) Natural convection of air in a square cavity: a benchmark numerical solution, Int. J. Numer. Methods Fluids 3(3):249-264 (Ra=1e4, Pr=0.71: Nu=2.243, u_max=16.178, v_max=19.617). In-repo machine-readable copy: src/tensorlbm/heat_convection_benchmarks.py:62 de_vahl_davis_reference(1e4) -> 2.243. Audit cross-check: values match the standard published de Vahl Davis table.", "three_piece_verification": {"run_artifacts": "PASS at worktree level (3 JSON with full per-2000-step Nu history, non-empty, numbers recompute); FAIL at repository level: git ls-files on main lists only 6 source files + docs for this case dir - no runs/*.json (runs/ gitignored at .gitignore:108), no figures/*.png (merge-time artifact filtering). Numbers are therefore only checkable by re-running.", "benchmark_ref_vs_got": "MIXED: ref values correct and zero-hand-copy via in-repo table; v_max PASS (-1.51% @nx48); u_max PASS (+1.60% @nx32) is an extremum-selection artifact - the same run's mirror extremum |min u_x|=17.629 gives +8.97% FAIL; primary metric Nu FAILS the 5% door at every delivered grid (-23.35/-15.75/-9.10%)", "repro_cmd": "PASS for the covered grids (bit-identical nx=24 reproduction); INCOMPLETE for the headline nx=48 (not in repro.sh) and README quoted runtime 2x4.5min vs actual 4.3+2.1min"}, "invariants": {"energy_balance_Nu_left_over_Nu_right_minus_1_pct": {"nx24": 8.53, "nx32": 6.01, "nx48": 3.99, "must_be": "0 at steady state", "verdict": "VIOLATED (boundary-geometry inconsistency: temperature Dirichlet on nodes vs momentum half-way wall)"}, "mirror_antisymmetry_(u_min+u_max)/u_max_pct": {"nx24": -12.27, "nx32": -7.25, "nx48": -3.48, "must_be": "0 for the antisymmetric solution", "verdict": "VIOLATED"}, "time_convergence": "OK - all three grids reach machine-zero residual (resid_u~1e-15, resid_T~5e-14) with Nu drift <2e-12 over the last windows; under-convergence is NOT the error source"}, "level_rationale": "L2, not L3/L4. L2 holds: real non-placeholder code input->compute->output (run.py/ladder.py/make_figures.py/publish_report.py), genuine run artifacts, and an audit rerun that reproduced the nx=24 artifact field-by-field (Nu=1.719326, max|dNu|=0.0). L3 fails: the deliverable is a case harness over a PRE-EXISTING public API - no production/platform path touched, the library delta is diagnostic return-dict keys plus an optional early-stop (default None, no operator change), there is no tensor_benchmark_cases row (0 rows for this anchor) and no case-level test guard. L4 fails: Nu is -9.10% (nx=48) / -15.75% (nx=32) / -23.35% (nx=24) against the predeclared <5% door, i.e. the benchmark judgement substantively fails; the reported u_max PASS does not survive the mirror-extremum check (+8.97% at nx=32). Coverage of a ref value by a two-point Richardson bracket with undetermined order is not validation (board precedent m15457: predeclared criteria FAIL + ledger 0 rows => capped below L4).", "overstated_claims": ["'velocity criteria PASS <2%' holds only for the selected positive extremum; the mirror extremum is +8.97% at nx=32", "'the -15.75% comes mainly from coarse-grid discretisation rather than physics error' is not established: two-point Richardson with undetermined p cannot show it, and the 6.01% left/right wall heat-flux imbalance at the same resolution is a competing explanation", "README 'honest partial achievement / u,v pass the 5% door' understates the u_max selection issue"], "findings": ["F1 high: primary metric Nu fails the predeclared 5% door at all delivered grids (best -9.10% @nx=48) - benchmark validation not achieved (honestly reported, but the capability is not there)", "F2 medium-high: u_max PASS (+1.60% @nx32) is an extremum-selection artifact; |min u_x| in the same artifact JSON gives +8.97% FAIL; the field u_max_nd_neg existed in the artifact but was left out of the comparison table", "F3 medium: steady-state left/right wall heat-flux imbalance 6.01% (nx32) / 3.99% (nx48); at steady state the fluxes must be equal, so the Nu observable itself carries ~+-3% definitional uncertainty, same order as the 5% door", "F4 medium: tensor_benchmark_cases has 0 rows for anchor CASE-RAYLEIGH-BENARD-RA1E4 - the 'sole referee' table does not exist for this anchor", "F5 medium: main branch carries no runs/*.json (gitignored) and no figures/*.png (merge artifact filter); repro.sh covers only nx=24/32, not the headline nx=48; README runtime quote (2x4.5min) vs actual (4.3+2.1min)", "F6 medium-low: anchor slug says RAYLEIGH-BENARD while ref and implementation are the de Vahl Davis differentially-heated square cavity; the doc clarifies it but the ledger/anchor level still mismatches", "F7 medium-low: docs section 3 states tau_T=0.78213 whereas the artifact says 1.06338 (=3*alpha+0.5, alpha=0.187793); a downstream reader would back out alpha=0.094 (Pr=1.42) instead of 0.71", "F8 low: platform report id=14542 section 6 mislabels the grid pair ('nx=24 1.7193 -> nx=32 2.0389 (+18.59%)'; 2.0389 is the nx=48 value) while the adjacent Richardson uses the 32->48 pair", "F9 low: no case-level test guard; tests/test_thermal.py:169-179 asserts nu_grad2>0 (always true) and u_max>1e-4", "F10 low (accounting): mission 15464 is succeeded/accepted with empty fail_stage while its own report headline says 'Nu FAIL'; the platform's server_quality_audit on the same row already shows gate_valid=false, key_present=false"], "recommended_action": "Do NOT write off the anchor as validated. Open round 2 with (a) invariant gates first: |Nu_left/Nu_right-1|<0.5% and |(u_min+u_max)/u_max|<0.5% as pass/fail preconditions, (b) fix temperature Dirichlet vs momentum half-way wall geometry consistency and H definition, (c) nx=64/96 three-point order determination - accept only if the nx>=64 direct value enters the 5% door (no extrapolation-only acceptance), (d) register the anchor in tensor_benchmark_cases (metric=Nu, tol=0.05, plus u/v and both invariants) and align the slug with the de Vahl Davis geometry, (e) fix docs tau_T and the report grid label, extend repro.sh to nx=48, (f) record the honest partial-FAIL accounting instead of succeeded with empty fail_stage.", "not_run": ["Did not rerun nx=32/48 (nx=24 bit-identical reproduction already establishes reproducibility)", "Cluster job cj1185 (nx=64 order-determination probe, submitted 2026-11-12 02:43) was still queued (369 ahead) at audit close - no result, no conclusion drawn from it", "Did not modify any audited code (verification-only board audit)", "Did not verify SDAA/GPU paths (delivery is CPU float64)"], "scope_note": "Audited m15464 (succeeded, PR #1821 merge a32b9b08). Independently recomputed every metric from the delivered JSON, reran the nx=24 reproduction and the 53-test regression, and queried the benchmark ledger directly. Audit figure: figures/audit_m15814_ra1e4.png; full report: docs/audits/CASE-RAYLEIGH-BENARD-RA1E4-m15814-audit.md", "impl_notes": ["run.py is the delivered CLI driver (argparse -> simulate_natural_convection -> JSON artifact, 124 lines, non-placeholder)", "ladder.py = cluster shard entry; make_figures.py = PNG from JSON; publish_report.py = report poster", "src/tensorlbm/thermal.py:333-460 = audit-measured location of the only library delta: return-dict diagnostics (u_max_x/_neg, v_max_y/_neg, extrema positions, stopped_early/steps_done) + optional stop_tol_nu/stop_patience (default None, no operator change)"], "entry_note": "run.py:52 calls tensorlbm.thermal.simulate_natural_convection; CLI: python run.py --nx N --tau T --steps S --report-every K --out J"}$json$::jsonb, 'board-audit')
